html:
{# ==========================================================
   HELO & HELO SHOP
   Payment Entry - Thermal Receipt
   Paper: 80mm x 297mm

   Receive = سند قبض
   Pay     = سند صرف
========================================================== #}

{% set company = frappe.get_doc("Company", doc.company) %}

{% set is_receive = doc.payment_type == "Receive" %}
{% set is_pay = doc.payment_type == "Pay" %}

{% set party_name = doc.party_name or doc.party or "—" %}

{% if is_receive %}
    {% set amount = doc.received_amount or doc.paid_amount or 0 %}
    {% set currency = doc.paid_to_account_currency or doc.paid_from_account_currency or "" %}
{% else %}
    {% set amount = doc.paid_amount or doc.received_amount or 0 %}
    {% set currency = doc.paid_from_account_currency or doc.paid_to_account_currency or "" %}
{% endif %}


<div class="helo-payment" dir="rtl">


    <!-- ========================
         LOGO
    ========================= -->

    {% if company.company_logo %}

    <div class="logo">

        <img
            src="{{ company.company_logo }}"
            alt="{{ company.company_name }}"
        >

    </div>

    {% endif %}



    <!-- ========================
         COMPANY
    ========================= -->

    <div class="shop-name">

        {{ company.company_name or doc.company }}

    </div>


    {% if company.phone_no %}

    <div class="shop-info" dir="ltr">

        {{ company.phone_no }}

    </div>

    {% endif %}



    <div class="divider"></div>



    <!-- ========================
         DOCUMENT TYPE
    ========================= -->

    <div class="voucher-title">


        {% if is_receive %}

            سند قبض

            <small>
                RECEIPT
            </small>


        {% elif is_pay %}

            سند صرف

            <small>
                PAYMENT
            </small>


        {% else %}

            سند مالي

            <small>
                PAYMENT ENTRY
            </small>

        {% endif %}


    </div>



    <!-- ========================
         AMOUNT
    ========================= -->

    <div class="amount-label">

        المبلغ

    </div>


    <div class="amount">

        {{ frappe.utils.fmt_money(amount, currency=currency) }}

    </div>



    <div class="divider"></div>



    <!-- ========================
         DETAILS
    ========================= -->

    <table class="details-table">


        <!-- PARTY -->

        <tr>

            <th>

                {% if is_receive %}

                    استلمنا من

                {% elif is_pay %}

                    تم الدفع إلى

                {% else %}

                    الاسم

                {% endif %}

            </th>


            <td class="party-value">

                {{ party_name }}

            </td>

        </tr>



        <!-- DATE -->

        <tr>

            <th>
                التاريخ
            </th>

            <td dir="ltr">

                {% if doc.posting_date %}

                    {{
                        frappe.utils.formatdate(
                            doc.posting_date,
                            "dd/MM/yyyy"
                        )
                    }}

                {% else %}

                    —

                {% endif %}

            </td>

        </tr>



        <!-- TIME -->

        {% if doc.creation %}

        <tr>

            <th>
                الوقت
            </th>

            <td dir="ltr">

                {{
                    frappe.utils.format_time(
                        doc.creation,
                        "HH:mm"
                    )
                }}

            </td>

        </tr>

        {% endif %}



        <!-- PAYMENT METHOD -->

        {% if doc.mode_of_payment %}

        <tr>

            <th>
                طريقة الدفع
            </th>

            <td>

                {{ doc.mode_of_payment }}

            </td>

        </tr>

        {% endif %}



        <!-- REFERENCE -->

        {% if doc.reference_no %}

        <tr>

            <th>
                رقم المرجع
            </th>

            <td dir="ltr">

                {{ doc.reference_no }}

            </td>

        </tr>

        {% endif %}



        <!-- DOCUMENT NUMBER -->

        <tr>

            <th>
                رقم السند
            </th>

            <td
                class="document-number"
                dir="ltr"
            >

                {{ doc.name }}

            </td>

        </tr>


    </table>



    <!-- ========================
         REMARKS
    ========================= -->

    {% if doc.custom_notes %}

    <div class="divider"></div>


    <div class="remarks-title">

        البيان

    </div>


    <div class="remarks">

        {{ doc.custom_notes }}

    </div>

    {% endif %}



    <!-- ========================
         REFERENCES
    ========================= -->

    {% if doc.references and doc.references|length > 0 %}


    <div class="references">


        {% for row in doc.references %}


            {% if row.reference_name %}


            <div class="reference-row">


                <span dir="ltr">

                    {{ row.reference_name }}

                </span>


                {% if row.allocated_amount %}

                <strong dir="ltr">

                    {{
                        frappe.utils.fmt_money(
                            row.allocated_amount,
                            currency=currency
                        )
                    }}

                </strong>

                {% endif %}


            </div>


            {% endif %}


        {% endfor %}


    </div>


    {% endif %}



    <!-- ========================
         FOOTER
    ========================= -->

    <div class="footer">

        شكراً لتعاملكم معنا

        <div class="footer-en">

            Thank You

        </div>

    </div>


</div>



<style>


/* ==========================================================
   THERMAL PAPER
========================================================== */

@page {

    size: 80mm 297mm;

    margin: 0 !important;

}



* {

    box-sizing: border-box !important;

}



html,
body {

    width: 80mm !important;

    max-width: 80mm !important;

    margin: 0 !important;

    padding: 0 !important;

    background: #fff !important;

}



.print-format {

    width: 80mm !important;

    max-width: 80mm !important;

    min-width: 80mm !important;

    margin: 0 !important;

    padding: 0 !important;

}



/* ==========================================================
   RECEIPT

   IMPORTANT:
   Physical paper = 80mm
   Safe printable content = 72mm
========================================================== */

.helo-payment {

    display: block;

    width: 72mm !important;

    max-width: 72mm !important;

    min-width: 72mm !important;

    margin: 0 auto !important;

    padding:
        2mm
        1mm
        3mm !important;

    color: #000;

    background: #fff;

    direction: rtl;

    font-family:
        "Noto Sans Arabic",
        "DejaVu Sans",
        Tahoma,
        Arial,
        sans-serif;

    font-size: 11px;

    line-height: 1.35;

    overflow: hidden;

}



/* ==========================================================
   LOGO
========================================================== */

.logo {

    width: 100%;

    margin:
        0
        auto
        1mm;

    padding: 0;

    text-align: center;

}



.logo img {

    display: block;

    width: auto;

    max-width: 24mm;

    max-height: 17mm;

    margin: 0 auto;

    object-fit: contain;

}



/* ==========================================================
   COMPANY
========================================================== */

.shop-name {

    width: 100%;

    margin: 0;

    padding: 0;

    text-align: center;

    font-size: 14px;

    font-weight: 900;

    line-height: 1.25;

    overflow-wrap: anywhere;

}



.shop-info {

    width: 100%;

    margin-top: .5mm;

    text-align: center;

    font-size: 9px;

}



/* ==========================================================
   DIVIDER
========================================================== */

.divider {

    width: 100%;

    height: 0;

    margin:
        2mm
        0;

    padding: 0;

    border: 0;

    border-top:
        1px
        dashed
        #777;

}



/* ==========================================================
   TITLE
========================================================== */

.voucher-title {

    width: 100%;

    margin: 0;

    padding: 0;

    text-align: center;

    font-size: 18px;

    font-weight: 900;

    line-height: 1.15;

}



.voucher-title small {

    display: block;

    margin-top: .5mm;

    direction: ltr;

    text-align: center;

    font-size: 6px;

    font-weight: 800;

    letter-spacing: .5px;

}



/* ==========================================================
   AMOUNT
========================================================== */

.amount-label {

    width: 100%;

    margin-top: 2mm;

    text-align: center;

    font-size: 10px;

    font-weight: 800;

}



.amount {

    width: 100%;

    margin-top: 1mm;

    padding:
        2mm
        1mm;

    border:
        1.5px
        solid
        #000;

    border-radius: 1.5mm;

    direction: ltr;

    text-align: center;

    font-size: 20px;

    font-weight: 900;

    line-height: 1.15;

    white-space: normal;

    overflow-wrap: anywhere;

}



/* ==========================================================
   DETAILS TABLE

   TABLE USED INSTEAD OF FLEX
   FOR BETTER WKHTMLTOPDF / THERMAL SUPPORT
========================================================== */

.details-table {

    width: 100% !important;

    max-width: 100% !important;

    margin: 0;

    padding: 0;

    border: 0;

    border-collapse: collapse;

    border-spacing: 0;

    table-layout: fixed;

    direction: rtl;

}



.details-table tr {

    width: 100%;

    border-bottom:
        1px
        dotted
        #999;

}



.details-table tr:last-child {

    border-bottom: 0;

}



.details-table th {

    width: 25mm;

    padding:
        1.5mm
        0;

    vertical-align: middle;

    color: #333;

    background: transparent;

    font-size: 9px;

    font-weight: 800;

    line-height: 1.3;

    text-align: right;

    white-space: normal;

}



.details-table td {

    width: auto;

    padding:
        1.5mm
        1mm
        1.5mm
        0;

    vertical-align: middle;

    color: #000;

    background: transparent;

    font-size: 10px;

    font-weight: 800;

    line-height: 1.3;

    text-align: right;

    white-space: normal;

    overflow-wrap: anywhere;

    word-break: break-word;

}



.details-table td[dir="ltr"] {

    text-align: left;

}



.party-value {

    font-size: 11px !important;

    font-weight: 900 !important;

}



.document-number {

    font-size: 8px !important;

    letter-spacing: 0;

}



/* ==========================================================
   REMARKS
========================================================== */

.remarks-title {

    width: 100%;

    margin:
        0
        0
        1mm;

    font-size: 10px;

    font-weight: 900;

    text-align: right;

}



.remarks {

    width: 100%;

    padding:
        1.5mm
        2mm;

    border:
        1px
        solid
        #aaa;

    border-radius: 1mm;

    font-size: 10px;

    line-height: 1.4;

    text-align: right;

    white-space: pre-wrap;

    overflow-wrap: anywhere;

}



/* ==========================================================
   REFERENCES
========================================================== */

.references {

    width: 100%;

    margin-top: 1.5mm;

    padding-top: 1mm;

}



.reference-row {

    display: table;

    width: 100%;

    table-layout: fixed;

    padding:
        1mm
        0;

    border-bottom:
        1px
        dotted
        #bbb;

    font-size: 8px;

}



.reference-row span,
.reference-row strong {

    display: table-cell;

    width: 50%;

    vertical-align: top;

    overflow-wrap: anywhere;

}



.reference-row span {

    text-align: right;

}



.reference-row strong {

    text-align: left;

}



/* ==========================================================
   FOOTER
========================================================== */

.footer {

    width: 100%;

    margin-top: 3mm;

    padding-top: 1.5mm;

    border-top:
        1.5px
        solid
        #000;

    text-align: center;

    font-size: 9px;

    font-weight: 900;

    line-height: 1.3;

}



.footer-en {

    margin-top: .4mm;

    direction: ltr;

    text-align: center;

    font-size: 6px;

    font-weight: 700;

}



/* ==========================================================
   PRINT
========================================================== */

@media print {


    html,
    body {

        width: 80mm !important;

        max-width: 80mm !important;

        min-width: 80mm !important;

        margin: 0 !important;

        padding: 0 !important;

    }


    .print-format {

        width: 80mm !important;

        max-width: 80mm !important;

        min-width: 80mm !important;

        margin: 0 !important;

        padding: 0 !important;

    }


    .helo-payment {

        width: 72mm !important;

        max-width: 72mm !important;

        min-width: 72mm !important;

        margin:
            0
            auto !important;

        padding:
            2mm
            1mm
            3mm !important;

        overflow: hidden !important;

        -webkit-print-color-adjust:
            exact !important;

        print-color-adjust:
            exact !important;

    }


    .details-table {

        width: 100% !important;

        max-width: 100% !important;

    }


}


</style>
